solution.code:
var cart = [
  { price: 5, qty: 2 },
  { price: 3, qty: 4 },
  { price: 10, qty: 1 }
];
var total = cart.reduce(function (sum, item) {
  return sum + item.price * item.qty;
}, 0);
console.log(total);
